from flowweaver_runtime import get_input, set_output


def scrub(value):
    if isinstance(value, str) and "{{" in value and "}}" in value:
        return ""
    if isinstance(value, list):
        return [scrub(v) for v in value]
    if isinstance(value, dict):
        return {k: scrub(v) for k, v in value.items()}
    return value


def run(ctx):
    inp = get_input()
    fetch = scrub(inp['steps']['fetch-netbox-devices']['output'])
    data = fetch.get('data') or {}
    results = data.get('results') or []

    rows = []
    for d in results:
        primary_ip4 = d.get('primary_ip4') or {}
        site = d.get('site') or {}
        role = d.get('role') or {}
        platform = d.get('platform') or {}
        status = d.get('status') or {}

        rows.append([
            d.get('name', '-'),
            primary_ip4.get('address', '-'),
            site.get('name', '-'),
            role.get('name', '-'),
            platform.get('name', '-'),
            status.get('label', '-')
        ])

    set_output({
        'rows': rows,
        'row_count': len(rows)
    })
